from pathlib import Path
import nbformat as n
root=Path(__file__).resolve().parent
b=n.v4.new_notebook();b.metadata={'kernelspec':{'display_name':'Python 3 (weather environment)','language':'python','name':'python3'}}
cells=[]
def md(s):cells.append(n.v4.new_markdown_cell(s))
def code(s):cells.append(n.v4.new_code_cell(s))
md('# Nepal forest-fire analysis: full 238-location experiment\n\nRun date: 4 November 2026. This notebook exposes the data audit, preparation decisions, actual model pipelines and saved experimental evidence. Earlier 2016 results were explored during this project, so this evaluation is retrospective.\n\nUse the project Python environment documented in `research_full/README.md`. Set `REBUILD_RAW` and `RETRAIN` below to repeat computational stages. The default verifies and displays the completed run without overwriting fitted outputs.')
code("from pathlib import Path\nimport json, hashlib\nimport numpy as np\nimport pandas as pd\nimport matplotlib.pyplot as plt\nimport reanalysis_2026 as analysis\nROOT = Path.cwd()\nDATA, OUT = analysis.DATA, analysis.OUT\nREBUILD_RAW = False\nRETRAIN = False\nif REBUILD_RAW:\n    data, features = analysis.ex.prepare()\nelse:\n    data = pd.read_csv(DATA / 'forest_fire_grid_daily.csv', parse_dates=['date'])\n    features = json.loads((DATA / 'feature_columns.json').read_text())\nassert data.grid_id.nunique() == 238\nassert not data.duplicated(['grid_id','date']).any()\nassert np.isfinite(data[features].to_numpy()).all()\nprint('Rows:', len(data), 'Positive cell-days:', int(data.fire_detected.sum()), 'Features:', len(features))")
md('## 1. Inspect the original data and audit\n\nAdministrative missing values are recorded but those fields are excluded from predictors. Exact duplicate rows differ from repeated detection keys. See the raw-audit and preparation-audit files for the coordinate range, excluded observations and target definition.')
code("display(pd.Series(json.loads((OUT / 'raw_audit.json').read_text())))\ndisplay(pd.read_csv(OUT / 'source_missingness.csv'))\ndisplay(pd.Series(json.loads((DATA / 'preparation_audit.json').read_text())))\nw = pd.read_csv(OUT / 'weather_audit.csv')\nassert len(w) == 238 and w['rows'].eq(1827).all()\nassert w['missing'].eq(0).all() and w['duplicate_dates'].eq(0).all()\nassert w['finite'].all()\ndisplay(w.head())")
md('## 2. Feature construction and partition checks\n\nEach target date uses weather only through its preceding day. Rainfall windows are 1, 7 and 30 days; seasonal sine/cosine and fixed forest/terrain summaries complete 21 predictors. Detection-derived fields are excluded. The raw preparation function is executable below; it is not a manually written substitute for the implementation.')
code("import inspect\nimport prepare_assignment\nprint(inspect.getsource(prepare_assignment.main))\nprint('Predictors:', features)\nassert not {'fire_detected','detection_count','national_detection_recorded','CONFIDENCE','FRP'} & set(features)\nsplit_summary = data.groupby('split').fire_detected.agg(['size','sum','mean'])\ndisplay(split_summary)\ntr = data[data.split.eq('train')]; va = data[data.split.eq('validation')]; te = data[data.split.eq('test')]\nassert tr.date.max() < va.date.min() < va.date.max() < te.date.min()\ndisplay(pd.read_csv(OUT / 'feature_audit.csv'))")
md('## 3. Explore distributions, correlations and imbalance\n\nNo Gaussian distribution is assumed and plausible extremes are retained. Statistics used to choose representations come from training observations.')
code("from IPython.display import display, Image\nfor name in ['preparation_flow','coverage_counts','imbalance','distributions','correlation']:\n    display(Image(filename=str(analysis.BASE / 'overleaf/images' / (name + '.png'))))")
md('## 4. Fit the four model families and controlled preprocessing variants\n\nTwelve main candidates use class weighting. Configuration selection uses 2015 AP; binary thresholds maximise validation F1. Accuracy-focused thresholds are a separate experiment. Scaling, PCA and SMOTE are fitted on training data only. PCA retains 95% of training variance; SMOTE uses five neighbours and a 0.10 minority/majority ratio.\n\n`RETRAIN=True` repeats fitting, tuning, uncertainty, feature importance, weather ablation, geographic evaluation and the five preprocessing variants. It will overwrite this full-run output directory, but not earlier experiment snapshots or source observations.')
code("print(inspect.getsource(analysis.ex.candidates))\nprint(inspect.getsource(analysis.extra))\nif RETRAIN:\n    analysis.ex.run(data, features)\n    analysis.extra(data, features)\ndisplay(pd.read_csv(OUT / 'tuning.csv')[['model','configuration','fit_seconds','validation_ap','f1_threshold']])")
md('## 5. Compare measured results and prediction errors\n\nBalanced accuracy is distinct from ordinary accuracy. No result is limited to a requested percentage. The later test is not used to choose the winning configuration.')
code("metrics = pd.read_csv(OUT / 'metrics.csv')\ndisplay(metrics.query(\"split == 'test' and policy == 'F1'\"))\ndisplay(pd.read_csv(OUT / 'preprocessing_ablation.csv'))\ndisplay(pd.read_csv(OUT / 'forward_2014.csv'))\ndisplay(pd.read_csv(OUT / 'spatial_diagnostic.csv'))\ndisplay(pd.read_csv(OUT / 'ablation.csv'))\ndisplay(pd.read_csv(OUT / 'ap_intervals.csv'))\nfor name in ['accuracy_recall','curves','confusions','pca','preprocessing','diagnostics','importance','historical_map']:\n    display(Image(filename=str(analysis.BASE / 'overleaf/images' / (name + '.png'))))")
md('## 6. Reproducibility and limits\n\nSatellite non-detections are unverified negatives; the full weather footprint does not make the fire archive complete. ERA5 is retrospective and coarse, forest cover is fixed at 2011, observations are dependent, and some test labels were seen in earlier work. The source manifest, data hash and settings identify the run. A later untouched observation period is required for stronger generalisation evidence.')
code("summary = json.loads((OUT / 'summary.json').read_text())\ndigest = hashlib.sha256((DATA / 'forest_fire_grid_daily.csv').read_bytes()).hexdigest()\nassert digest == summary['data_sha256']\nprint('Verified dataset hash:', digest)\ndisplay(pd.Series(summary))")
b.cells=cells
n.write(b,root/'Nepal_Forest_Fire_Full_Analysis.ipynb')
print('Created notebook with',len(cells),'cells')
